 readonly PanelDevice panel=new();readonly SensorService sensorService=new();readonly StudioProject project=ProjectStore.Load();readonly StudioCanvas canvas=new(){Dock=DockStyle.Fill};readonly System.Windows.Forms.Timer timer=new(){Interval=500};readonly NotifyIcon tray=new();
 readonly Color bg=Color.FromArgb(7,11,19),side=Color.FromArgb(10,16,27),surface=Color.FromArgb(14,22,37),surface2=Color.FromArgb(20,31,51),line=Color.FromArgb(39,53,79),fg=Color.FromArgb(240,245,255),muted=Color.FromArgb(135,152,181),accent=Color.FromArgb(78,83,244),cyan=Color.FromArgb(31,215,255);
