 public MainForm(){Text="LOVINGCOOL Studio";WindowState=FormWindowState.Maximized;StartPosition=FormStartPosition.CenterScreen;MinimumSize=new(1360,820);BackColor=bg;ForeColor=fg;Font=new("Segoe UI",10);try{Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);}catch{}canvas.Project=project;canvas.SelectionChanged+=Select;Build();RefreshSensors();RefreshLayers();SetupTray();timer.Tick+=(_,_)=>Tick();timer.Start();FormClosing+=(_,_)=>{ProjectStore.Save(project);panel.Dispose();sensorService.Dispose();tray.Visible=false;};}
 Label L(string t,int s=10,bool b=false)=>new(){Text=t,AutoSize=true,ForeColor=b?fg:muted,Font=new("Segoe UI",s,b?FontStyle.Bold:FontStyle.Regular)};
