 void Build(){var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,BackColor=bg};root.ColumnStyles.Add(new(SizeType.Absolute,220));root.ColumnStyles.Add(new(SizeType.Absolute,260));root.ColumnStyles.Add(new(SizeType.Percent,100));root.ColumnStyles.Add(new(SizeType.Absolute,340));Controls.Add(root);Side(root);Library(root);Workspace(root);Inspector(root);}
 void Side(TableLayoutPanel r){var p=new Panel{Dock=DockStyle.Fill,BackColor=side,Padding=new Padding(16)};r.Controls.Add(p,0,0);var logo=L("◈  LOVINGCOOL\n    STUDIO",16,true);logo.Dock=DockStyle.Top;logo.Height=70;p.Controls.Add(logo);var nav=new FlowLayoutPanel{Dock=DockStyle.Top,Height=390,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(0,12,0,0)};p.Controls.Add(nav);
