 var foot=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=235,FlowDirection=FlowDirection.TopDown,WrapContents=false};p.Controls.Add(foot);device.Text="● LOVINGCOOL 6 PRO\n  отключено";device.ForeColor=muted;device.Width=188;device.Height=42;foot.Controls.Add(device);foot.Controls.Add(L("ЯРКОСТЬ",8,true));var br=new TrackBar{Width=188,Minimum=5,Maximum=100,Value=project.Brightness,TickStyle=TickStyle.None};br.ValueChanged+=(_,_)=>{project.Brightness=br.Value;if(panel.Connected)panel.SetBrightness(br.Value);};foot.Controls.Add(br);var c=B("Подключить",(_,_)=>Connect(),true);c.Width=188;foot.Controls.Add(c);var tr=B("Свернуть в трей",(_,_)=>Hide());tr.Width=188;foot.Controls.Add(tr);}
